public final class StringUtils {
    // Suppress default constructor for noninstantiability
    private StringUtils() {
        throw new AssertionError("No StringUtils instances for you!");
    }

    public static boolean isBlank(String s) { return s == null || s.isBlank(); }
}

// Bad: Hardcoded resource singleton
public class SpellChecker {
    private static final Lexicon dictionary = new EnglishDictionary();
}

// Good: Dependency injection
public class SpellChecker {
    private final Lexicon dictionary;
    public SpellChecker(Lexicon dictionary) {
        this.dictionary = Objects.requireNonNull(dictionary);
    }
}

// BAD (Compiles a new Pattern on every call):
static boolean isRoman(String s) {
    return s.matches("^(?=.)M*(C[MD]|D?C{0,3})(X[CL]|L?X{0,3})(I[XV]|V?I{0,3})$");
}

// GOOD (Reuses compiled Pattern):
private static final Pattern ROMAN = Pattern.compile(
    "^(?=.)M*(C[MD]|D?C{0,3})(X[CL]|L?X{0,3})(I[XV]|V?I{0,3})$");

static boolean isRomanFast(String s) {
    return ROMAN.matcher(s).matches();
}

public Object pop() {
    if (size == 0) throw new EmptyStackException();
    Object result = elements[--size];
    elements[size] = null; // Eliminate obsolete reference!
    return result;
}

// PROPER RESOURCE CLEANUP:
public class Room implements AutoCloseable {
    @Override
    public void close() {
        // Guaranteed immediate prompt cleanup!
        cleanUpNativeResources();
    }
}
